         if (response.status === 401) {
           this.session = null;
           this.equipment = [];
           this.catalogueError = 'Please sign in again.';
         } else {
           this.catalogueError = 'Unable to load the equipment catalogue.';
         }
         return;
       }
       this.equipment = await response.json() as Equipment[];
